/**
 * The Topup Database: built into the app (`topupBuiltIn.json`, generated by `npm run topup-data`
 * from the workbook `QRCode for Topup.xlsm`), overridden by `topup.dat` in the data folder, sealed
 * and shared by every PC, once a workbook is imported. An import reads the workbook's DataBase sheet
 * and replaces `topup.dat` only if it is accepted, so a refused workbook never replaces the database
 * in use. Every import is written to the import log.
 */
import {
  indexTopup,
  parseTopupDatabase,
  TOPUP_SHEET_NAME,
  type TopupDatabaseInfo,
  type TopupDatabaseSummary,
  type TopupEntry,
  type TopupImportResult,
  type TopupIndex
} from '../core/topup'
import type { BadRow } from '../core/itemList'
import { errorText } from './atomicWrite'
import { importLogWarning, type ImportLogEntry } from './importLog'
import { platform } from './platform'
import { readSealed, writeSealed } from './sealed'
import { createSharedFile } from './sharedFile'
import builtInData from './topupBuiltIn.json'
import { readWorkbookSheet } from './workbook'

export const TOPUP_FILE_NAME = 'topup.dat'

/** A larger file is refused unread (the workbook is about 1 MB). */
export const MAX_TOPUP_FILE_BYTES = 64 * 1024 * 1024

/** An entry as stored: [Item Code, Display Name (MOE), Salt / Special Property (MOE), Form Code]. */
export type TopupRow = readonly [itemCode: string, displayName: string, salt: string, formCode: string]

/** What `topup.dat` holds. */
export interface StoredTopupDatabase {
  readonly sourceFileName: string
  /** The imported workbook's last-modified time, ISO 8601. */
  readonly sourceModified: string
  /** ISO 8601. */
  readonly importedAt: string
  readonly importedBy: string
  readonly pc: string
  readonly entries: readonly TopupRow[]
}

/** A Topup Database ready to use. */
export interface LoadedTopupDatabase {
  readonly info: TopupDatabaseInfo
  readonly index: TopupIndex
}

export function topupPath(dataFolder: string): string {
  return platform().path.join(dataFolder, TOPUP_FILE_NAME)
}

let builtIn: LoadedTopupDatabase | null = null

/** The Topup Database built into the app. */
export function builtInTopupDatabase(): LoadedTopupDatabase {
  builtIn ??= loaded(
    { source: 'built-in', sourceFileName: builtInData.sourceFileName, sourceModified: builtInData.sourceModified, importedAt: null, importedBy: null, pc: null },
    builtInData.entries as unknown as readonly TopupRow[]
  )
  return builtIn
}

export type LoadTopupResult =
  | { status: 'ok'; database: LoadedTopupDatabase }
  | { status: 'missing' }
  | { status: 'tampered'; message: string }
  | { status: 'unreadable'; message: string }

/** Reads `topup.dat`: the imported Topup Database, or why there is none to use. */
export async function loadTopupDatabase(dataFolder: string): Promise<LoadTopupResult> {
  const read = await readSealed(topupPath(dataFolder))
  switch (read.status) {
    case 'missing':
      return read
    case 'tampered':
      return { status: 'tampered', message: `The Topup Database (${TOPUP_FILE_NAME}) was changed outside the app.` }
    case 'unreadable':
      return { status: 'unreadable', message: `The Topup Database could not be used: ${read.message}` }
    case 'ok': {
      const stored = asStoredTopup(read.value)
      if (stored) return { status: 'ok', database: loadedFromStored(stored) }
      return { status: 'unreadable', message: `The Topup Database (${TOPUP_FILE_NAME}) is not a valid Topup Database.` }
    }
  }
}

export interface TopupImportContext {
  readonly dataFolder: string
  /** Where this PC's import log goes. */
  readonly logFolder: string
  readonly pcName: string
  readonly windowsUser: string
  now(): Date
}

/**
 * Imports the workbook at `sourcePath` (`.xlsm` or `.xlsx`) as the Topup Database and logs the
 * import. On success `topup.dat` is replaced and the new database returned; otherwise nothing changes.
 */
export async function importTopupFile(
  sourcePath: string,
  context: TopupImportContext
): Promise<{ result: TopupImportResult; database: LoadedTopupDatabase | null }> {
  const at = context.now()

  async function logged(result: TopupImportResult, line: Pick<ImportLogEntry, 'rowsImported' | 'badRows' | 'result'>): Promise<TopupImportResult> {
    const warning = await importLogWarning(context.logFolder, { at, windowsUser: context.windowsUser, pcName: context.pcName, kind: 'Topup Database', file: sourcePath, ...line })
    return warning ? { ...result, warning } : result
  }

  async function notImported(
    outcome: 'Refused' | 'Failed',
    message: string,
    parsed?: { summary: TopupDatabaseSummary; badRows: readonly BadRow[] }
  ): Promise<{ result: TopupImportResult; database: null }> {
    const result = await logged(
      { status: 'refused', message, summary: parsed?.summary ?? null, badRows: parsed?.badRows ?? [], warning: null },
      { rowsImported: 0, badRows: parsed?.summary.badRows ?? 0, result: `${outcome}: ${message}` }
    )
    return { result, database: null }
  }

  let modified: Date
  let bytes: Uint8Array
  try {
    const stats = await platform().fs.stat(sourcePath)
    if (stats.size > MAX_TOPUP_FILE_BYTES) {
      return notImported('Refused', `The file is too large to be the Topup workbook (${Math.ceil(stats.size / (1024 * 1024))} MB).`)
    }
    modified = new Date(stats.mtimeMs)
    bytes = await platform().fs.readFile(sourcePath)
  } catch (error) {
    return notImported('Failed', `The file could not be read: ${errorText(error)}`)
  }

  const sheet = await readWorkbookSheet(bytes, TOPUP_SHEET_NAME)
  if (!sheet.ok) return notImported('Refused', sheet.message)
  const parsed = parseTopupDatabase(sheet.rows)
  if (!parsed.ok) return notImported('Refused', parsed.message, parsed)

  const stored: StoredTopupDatabase = {
    sourceFileName: platform().path.basename(sourcePath),
    sourceModified: modified.toISOString(),
    importedAt: at.toISOString(),
    importedBy: context.windowsUser,
    pc: context.pcName,
    entries: parsed.entries.map((entry) => [entry.itemCode, entry.displayName, entry.salt, entry.formCode] as const)
  }
  try {
    await writeSealed(topupPath(context.dataFolder), stored)
  } catch (error) {
    return notImported('Failed', `The Topup Database could not be saved: ${errorText(error)}`, parsed)
  }

  const database = loadedFromStored(stored, parsed.entries)
  const result = await logged(
    { status: 'imported', info: database.info, summary: parsed.summary, badRows: parsed.badRows, warning: null },
    { rowsImported: parsed.summary.entries, badRows: parsed.summary.badRows, result: 'Imported' }
  )
  return { result, database }
}

/** The Topup Database in use on this PC: the imported one when there is one that can be used, else the built-in one. */
export interface TopupSource {
  /** Reads `topup.dat` (at startup). */
  load(): Promise<LoadTopupResult>
  /** The database in use, first reloaded if another PC has imported a newer one since. */
  current(): Promise<LoadedTopupDatabase>
  /** Imports a workbook; an accepted one becomes the database in use. */
  importFile(sourcePath: string, context: Omit<TopupImportContext, 'dataFolder'>): Promise<TopupImportResult>
}

export function createTopupSource(dataFolder: string): TopupSource {
  const file = createSharedFile(
    topupPath(dataFolder),
    () => loadTopupDatabase(dataFolder),
    (result) => (result.status === 'ok' ? result.database : null)
  )
  return {
    load: file.load,
    current: async () => (await file.current()) ?? builtInTopupDatabase(),
    async importFile(sourcePath, context) {
      const { result, database } = await importTopupFile(sourcePath, { ...context, dataFolder })
      if (database) await file.replaced(database)
      return result
    }
  }
}

function loadedFromStored(stored: StoredTopupDatabase, entries?: readonly TopupEntry[]): LoadedTopupDatabase {
  const { sourceFileName, sourceModified, importedAt, importedBy, pc } = stored
  return loaded({ source: 'imported', sourceFileName, sourceModified, importedAt, importedBy, pc }, stored.entries, entries)
}

function loaded(info: Omit<TopupDatabaseInfo, 'entries'>, rows: readonly TopupRow[], entries?: readonly TopupEntry[]): LoadedTopupDatabase {
  const index = indexTopup(entries ?? rows.map(([itemCode, displayName, salt, formCode]) => ({ itemCode, displayName, salt, formCode })))
  return { info: { ...info, entries: index.size }, index }
}

/** The stored Topup Database, if `value` is one (every entry four strings). */
function asStoredTopup(value: unknown): StoredTopupDatabase | null {
  if (typeof value !== 'object' || value === null) return null
  const record = value as Record<string, unknown>
  const strings = ['sourceFileName', 'sourceModified', 'importedAt', 'importedBy', 'pc'] as const
  if (!strings.every((key) => typeof record[key] === 'string')) return null
  const { entries } = record
  if (!Array.isArray(entries)) return null
  const valid = entries.every((row: unknown) => Array.isArray(row) && row.length === 4 && row.every((cell) => typeof cell === 'string'))
  return valid ? (record as unknown as StoredTopupDatabase) : null
}
